  const money = (v, currency = 'PKR') => `${currency === 'PKR' ? 'Rs' : currency} ${Number(v || 0).toLocaleString('en-PK')}`;
  const date = (v, fallback = 'Not set') => { if (!v) return fallback; const d = new Date(v); return Number.isNaN(d.getTime()) ? esc(v) : d.toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}); };
  const datetimeLocal = (v) => { if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16); };
  const timeAgo = (v) => { const d = new Date(v); if (Number.isNaN(d.getTime())) return ''; const s = Math.max(1,(Date.now()-d.getTime())/1000); if(s<60)return 'now'; if(s<3600)return `${Math.floor(s/60)}m`; if(s<86400)return `${Math.floor(s/3600)}h`; if(s<604800)return `${Math.floor(s/86400)}d`; return date(v); };
